        stg_order_items.order_id,
        stg_order_items.product_id
    from {{ ref('stg_order_items') }} as stg_order_items
),

sq_stg_orders as (
    -- Source Qualifier SQ_STG_ORDERS
    select
        stg_orders.order_id,
        stg_orders.customer_id,
        stg_orders.location_id,
        stg_orders.ordered_at_day,
        stg_orders.subtotal_cents,
        stg_orders.tax_paid_cents,
        stg_orders.order_total_cents,
        stg_orders.subtotal,
        stg_orders.tax_paid,
        stg_orders.order_total
    from {{ ref('stg_orders') }} as stg_orders
),

jnr_items_orders as (
    -- Joiner JNR_ITEMS_ORDERS
    -- Normal Join (master sq_stg_order_items, detail sq_stg_orders)
    select
        sq_stg_order_items.order_item_id,
        sq_stg_order_items.order_id,
        sq_stg_order_items.product_id,
        sq_stg_orders.customer_id,
        sq_stg_orders.location_id,
        sq_stg_orders.ordered_at_day
    from sq_stg_orders
        inner join sq_stg_order_items
            on sq_stg_order_items.order_id = sq_stg_orders.order_id
),

sq_stg_products as (
    -- Source Qualifier SQ_STG_PRODUCTS
    select
        stg_products.product_id,
        stg_products.product_name,
        stg_products.product_type,
        stg_products.product_price_cents,
        stg_products.product_price,
        stg_products.product_description,
        stg_products.is_food_item,
        stg_products.is_drink_item
    from {{ ref('stg_products') }} as stg_products
),

jnr_add_products as (
    -- Joiner JNR_ADD_PRODUCTS
    -- Normal Join (master jnr_items_orders, detail sq_stg_products)
    select
        jnr_items_orders.order_item_id,
        jnr_items_orders.order_id,
        jnr_items_orders.product_id,
        jnr_items_orders.customer_id,
        jnr_items_orders.location_id,
