    from {{ ref('stg_locations') }} as stg_locations
),

jnr_add_locations as (
    -- Joiner JNR_ADD_LOCATIONS
    -- Master Outer Join (master jnr_add_customers, detail sq_stg_locations)
    select
        jnr_add_customers.order_item_id,
        jnr_add_customers.order_id,
