    from {{ ref('stg_supplies') }} as stg_supplies
),

srt_supplies as (
    -- Sorter SRT_SUPPLIES
    -- sort order dropped: a table or view has no row order
    select
        sq_stg_supplies.product_id,
        sq_stg_supplies.supply_cost,
        sq_stg_supplies.is_perishable
    from sq_stg_supplies
),

agg_supplies_by_product as (
    -- Aggregator AGG_SUPPLIES_BY_PRODUCT
    select
        srt_supplies.product_id,
        sum(srt_supplies.supply_cost) as supply_cost_per_product,
        max(srt_supplies.is_perishable) as has_perishable_supply
    from srt_supplies
    group by srt_supplies.product_id
),

jnr_add_supplies as (
    -- Joiner JNR_ADD_SUPPLIES
    -- Master Outer Join (master jnr_add_locations, detail agg_supplies_by_product)
    select
        jnr_add_locations.order_item_id,
        jnr_add_locations.order_id,
        jnr_add_locations.product_id,
        jnr_add_locations.customer_id,
        jnr_add_locations.location_id,
        jnr_add_locations.ordered_at_day,
        jnr_add_locations.product_name,
        jnr_add_locations.product_type,
        jnr_add_locations.product_price,
