        jnr_add_locations.is_drink_item,
        jnr_add_locations.customer_name,
        jnr_add_locations.location_name,
        jnr_add_locations.tax_rate,
        jnr_add_locations.region,
        agg_supplies_by_product.supply_cost_per_product,
        agg_supplies_by_product.has_perishable_supply
    from agg_supplies_by_product
        left join jnr_add_locations
            on jnr_add_locations.product_id = agg_supplies_by_product.product_id
),

exp_item_calculations as (
    -- Expression EXP_ITEM_CALCULATIONS
    select
        jnr_add_supplies.order_item_id,
        jnr_add_supplies.order_id,
        jnr_add_supplies.product_id,
        jnr_add_supplies.customer_id,
        jnr_add_supplies.location_id,
        jnr_add_supplies.ordered_at_day,
        jnr_add_supplies.product_name,
        jnr_add_supplies.product_type,
        jnr_add_supplies.product_price,
        jnr_add_supplies.is_food_item,
        jnr_add_supplies.is_drink_item,
        coalesce(jnr_add_supplies.customer_name, 'Unknown') as customer_name,
        coalesce(jnr_add_supplies.location_name, 'Unknown') as location_name,
        coalesce(jnr_add_supplies.region, 'Unknown') as region,
        jnr_add_supplies.product_price as item_revenue,
        coalesce(jnr_add_supplies.supply_cost_per_product, 0) as item_cogs,
        jnr_add_supplies.product_price - coalesce(jnr_add_supplies.supply_cost_per_product, 0) as item_gross_profit,
        case when jnr_add_supplies.product_price = 0 then 0 else (jnr_add_supplies.product_price - coalesce(jnr_add_supplies.supply_cost_per_product, 0)) / jnr_add_supplies.product_price end as item_gross_margin_pct,
        jnr_add_supplies.product_price * coalesce(jnr_add_supplies.tax_rate, 0) as item_tax_estimate,
        jnr_add_supplies.product_price + jnr_add_supplies.product_price * coalesce(jnr_add_supplies.tax_rate, 0) as item_total_estimate,
        coalesce(jnr_add_supplies.has_perishable_supply, 0) as has_perishable_supply
    from jnr_add_supplies
),

srt_order_id as (
