        exp_high_band.order_tax_paid,
        exp_high_band.order_total,
        exp_high_band.item_lines,
        exp_high_band.item_revenue,
        exp_high_band.order_cogs,
        exp_high_band.order_gross_profit,
        exp_high_band.order_gross_margin_pct,
        exp_high_band.effective_tax_rate,
        exp_high_band.food_item_lines,
        exp_high_band.drink_item_lines,
        exp_high_band.food_share_of_lines,
        exp_high_band.drink_share_of_lines,
        exp_high_band.customer_order_number,
        exp_high_band.order_value_band
    from exp_high_band

    union all

    -- input group EXP_STD_BAND
    select
        exp_std_band.order_id,
        exp_std_band.customer_id,
        exp_std_band.location_id,
        exp_std_band.ordered_at_day,
        exp_std_band.order_subtotal,
        exp_std_band.order_tax_paid,
        exp_std_band.order_total,
        exp_std_band.item_lines,
        exp_std_band.item_revenue,
        exp_std_band.order_cogs,
        exp_std_band.order_gross_profit,
        exp_std_band.order_gross_margin_pct,
        exp_std_band.effective_tax_rate,
        exp_std_band.food_item_lines,
        exp_std_band.drink_item_lines,
        exp_std_band.food_share_of_lines,
        exp_std_band.drink_share_of_lines,
        exp_std_band.customer_order_number,
        exp_std_band.order_value_band
    from exp_std_band
),

srt_before_agg as (
    -- Sorter SRT_BEFORE_AGG
    -- sort order dropped: a table or view has no row order
    select
        un_order_bands.location_id,
        un_order_bands.order_id,
        un_order_bands.customer_id,
        un_order_bands.ordered_at_day,
        un_order_bands.order_total,
        un_order_bands.order_subtotal,
        un_order_bands.order_tax_paid,
        un_order_bands.order_cogs,
        un_order_bands.order_gross_profit,
        un_order_bands.order_value_band
    from un_order_bands
),

srt_for_distinct_customer as (
    -- Sorter SRT_FOR_DISTINCT_CUSTOMER
    -- sort order dropped: a table or view has no row order
    select
        srt_before_agg.location_id,
        srt_before_agg.ordered_at_day,
        srt_before_agg.customer_id,
        srt_before_agg.order_id,
        srt_before_agg.order_total,
        srt_before_agg.order_subtotal,
        srt_before_agg.order_tax_paid,
        srt_before_agg.order_cogs,
        srt_before_agg.order_gross_profit,
        srt_before_agg.order_value_band
    from srt_before_agg
),

exp_mark_first_customer as (
    -- Expression EXP_MARK_FIRST_CUSTOMER
    select
        srt_for_distinct_customer.location_id,
        srt_for_distinct_customer.ordered_at_day,
        srt_for_distinct_customer.customer_id,
        srt_for_distinct_customer.order_id,
        srt_for_distinct_customer.order_total,
        srt_for_distinct_customer.order_subtotal,
        srt_for_distinct_customer.order_tax_paid,
        srt_for_distinct_customer.order_cogs,
        srt_for_distinct_customer.order_gross_profit,
        srt_for_distinct_customer.order_value_band,
        case when srt_for_distinct_customer.location_id = srt_for_distinct_customer.location_id and srt_for_distinct_customer.ordered_at_day = srt_for_distinct_customer.ordered_at_day and srt_for_distinct_customer.customer_id = srt_for_distinct_customer.customer_id then 0 else 1 end as is_first_customer
    from srt_for_distinct_customer
),

agg_by_location_day as (
    -- Aggregator AGG_BY_LOCATION_DAY
    select
        exp_mark_first_customer.location_id,
        exp_mark_first_customer.ordered_at_day,
        count(exp_mark_first_customer.order_id) as orders_count,
        sum(exp_mark_first_customer.is_first_customer) as unique_customers,
        sum(exp_mark_first_customer.order_total) as revenue_total,
        sum(exp_mark_first_customer.order_subtotal) as subtotal_total,
        sum(exp_mark_first_customer.order_tax_paid) as tax_total,
        sum(exp_mark_first_customer.order_cogs) as cogs_total,
        sum(exp_mark_first_customer.order_gross_profit) as gross_profit_total,
        sum(case when exp_mark_first_customer.order_value_band = 'HIGH' then 1 else 0 end) as high_value_orders
    from exp_mark_first_customer
    group by exp_mark_first_customer.location_id, exp_mark_first_customer.ordered_at_day
),

exp_store_kpis as (
    -- Expression EXP_STORE_KPIS
    select
        agg_by_location_day.location_id,
        agg_by_location_day.ordered_at_day,
        agg_by_location_day.orders_count,
        agg_by_location_day.unique_customers,
        agg_by_location_day.revenue_total,
        agg_by_location_day.subtotal_total,
        agg_by_location_day.tax_total,
        agg_by_location_day.cogs_total,
        agg_by_location_day.gross_profit_total,
        agg_by_location_day.high_value_orders,
        case when agg_by_location_day.subtotal_total = 0 then 0 else agg_by_location_day.gross_profit_total / agg_by_location_day.subtotal_total end as gross_margin_pct,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.revenue_total / agg_by_location_day.orders_count end as avg_order_value,
        case when agg_by_location_day.orders_count = 0 then 0 else agg_by_location_day.high_value_orders / agg_by_location_day.orders_count end as high_value_orders_pct
    from agg_by_location_day
),

sq_stg_locations1 as (
    -- Source Qualifier SQ_STG_LOCATIONS1
    select
        stg_locations1.location_id,
        stg_locations1.location_name,
        stg_locations1.opened_date,
        stg_locations1.tax_rate,
        stg_locations1.region
    from {{ ref('stg_locations') }} as stg_locations1
),

jnr_add_location_info as (
    -- Joiner JNR_ADD_LOCATION_INFO
    -- Master Outer Join (master exp_store_kpis, detail sq_stg_locations1)
    select
        exp_store_kpis.location_id,
        sq_stg_locations1.location_name,
        sq_stg_locations1.region,
        exp_store_kpis.ordered_at_day,
        exp_store_kpis.orders_count,
        exp_store_kpis.unique_customers,
        exp_store_kpis.revenue_total,
        exp_store_kpis.subtotal_total,
        exp_store_kpis.tax_total,
        exp_store_kpis.cogs_total,
        exp_store_kpis.gross_profit_total,
        exp_store_kpis.gross_margin_pct,
        exp_store_kpis.avg_order_value,
        exp_store_kpis.high_value_orders,
        exp_store_kpis.high_value_orders_pct
    from sq_stg_locations1
        left join exp_store_kpis
            on exp_store_kpis.location_id = sq_stg_locations1.location_id
),

fil_locs as (
    -- Filter FIL_LOCS
    select
        jnr_add_location_info.location_id,
        jnr_add_location_info.location_name,
        jnr_add_location_info.region,
        jnr_add_location_info.ordered_at_day,
        jnr_add_location_info.orders_count,
        jnr_add_location_info.unique_customers,
        jnr_add_location_info.revenue_total,
        jnr_add_location_info.subtotal_total,
        jnr_add_location_info.tax_total,
        jnr_add_location_info.cogs_total,
        jnr_add_location_info.gross_profit_total,
        jnr_add_location_info.gross_margin_pct,
        jnr_add_location_info.avg_order_value,
        jnr_add_location_info.high_value_orders,
        jnr_add_location_info.high_value_orders_pct
    from jnr_add_location_info
    where not jnr_add_location_info.location_id is null
)

select
    fil_locs.location_id,
    fil_locs.location_name,
    fil_locs.region,
    fil_locs.ordered_at_day,
    fil_locs.orders_count,
    fil_locs.unique_customers,
    fil_locs.revenue_total,
    fil_locs.subtotal_total,
    fil_locs.tax_total,
    fil_locs.cogs_total,
    fil_locs.gross_profit_total,
    fil_locs.gross_margin_pct,
    fil_locs.avg_order_value,
    fil_locs.high_value_orders,
    fil_locs.high_value_orders_pct
from fil_locs
